        },
        {
            "title": "Bazooka Insect",
            "humor": 7,
            "why": "Combines violent explosive energy with a tiny bug, creating an over-the-top image of a small insect carrying or being launched by a bazooka."
        },
        {
            "title": "Basic Intact",
            "humor": 5,
            "why": "A more wholesome mishearing; funny because it suggests someone’s primal urges are still untouched, but the joke is less edgy and visual."
        },
        {
            "title": "Bassic Instinct",
            "humor": 4,
            "why": "Just a slight misspelling that implies low-quality bass music; it’s cute but not as immediately funny or adult."
